.VerifyText <- function(file) {
  con <- file(
    description = file,
    open = "rb"
  )
  head_bytes <- readBin(
    con = con,
    what = "raw",
    n = 8000
  )
  close(con = con)
  # NULL for binary files
  if (!any(head_bytes == as.raw(x = 0))) {
    lines <- sub(
      pattern = "\r$",
      replacement = "",
      x = readLines(
        con = file,
        warn = FALSE
      )
    )
    # generated by roxygen during make
    if (basename(path = file) == "DESCRIPTION") {
      lines <- lines[!grepl(pattern = "^Config/roxygen2/version:", x = lines)]
    }
    # Overleaf can add or drop the final newline and trailing blank lines
    keep <- which(x = nzchar(x = trimws(x = lines)))
    lines[seq_len(length.out = max(c(0L, keep)))]
  }
}
